// Precompiles every EJS view into plain JS functions so they can run on
// Cloudflare Workers (which forbids eval/new Function at runtime).
// Output: src/templates.gen.mjs  (generated — do not edit)
const fs = require('fs');
const path = require('path');
const ejs = require('ejs');

const VIEWS = path.join(__dirname, '..', 'views');
const OUT = path.join(__dirname, '..', 'src', 'templates.gen.mjs');

// Every variable name templates may reference. They are destructured from `locals`
// because Workers code runs in strict mode (no `with`).
const NAMES = [
  's', 'sec', 'navServices', 'navIndustries', 'icon', 'md', 'clip', 'fmtDate', 'readTime', 'path', 'year', 'seo',
  'services', 'projects', 'posts', 'sv', 'p', 'others', 'list', 'cats', 'cat', 'q', 'page', 'pages', 'related', 'ind',
  'crumbs', 'title', 'lead', 'eyebrow', 'item', 'i', 'it', 'error', 'disabled', 'icons', 'big', 'eager',
];

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(d =>
    d.isDirectory() ? walk(path.join(dir, d.name)) : d.name.endsWith('.ejs') ? [path.join(dir, d.name)] : []);
}

const entries = walk(VIEWS).map(file => {
  const key = path.relative(VIEWS, file).replace(/\\/g, '/').replace(/\.ejs$/, '');
  const t = new ejs.Template(fs.readFileSync(file, 'utf8'), {
    client: true, strict: true, compileDebug: false, destructuredLocals: NAMES, filename: file,
  });
  t.compile(); // populates t.source (the generated function body)
  return `  ${JSON.stringify(key)}: function (locals, escapeFn, include) {\n${t.source}\n}`;
});

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, `// GENERATED by scripts/build-templates.js — do not edit\n/* eslint-disable */\nexport default {\n${entries.join(',\n')}\n};\n`);
console.log(`Compiled ${entries.length} templates → ${path.relative(process.cwd(), OUT)}`);
